const log = [];
async function snap(tag) {
  const txt = (await page.evaluate(() => document.body.innerText)) || '';
  const btns = await page.evaluate(() => {
    const out = [];
    const els = document.querySelectorAll('button, a[role=button], [class*=option], [class*=answer], input[type=submit]');
    for (let i = 0; i < els.length && out.length < 18; i++) {
      const t = (els[i].innerText || els[i].value || '').trim().replace(/\s+/g, ' ');
      if (t) out.push(t.slice(0, 45));
    }
    return out;
  });
  log.push({ tag: tag, url: page.url(), title: await page.title(), textLen: txt.length, text: txt.replace(/\s+/g, ' ').slice(0, 320), buttons: btns });
}

await page.goto('https://brainiqtest.com/', { waitUntil: 'domcontentloaded' });
await page.waitForTimeout(4000);
await snap('home');

try {
  const start = page.getByText(/Start Certified Test|Start IQ Test|Start the IQ test/i).first();
  await start.click({ timeout: 15000 });
} catch (e) {
  log.push({ tag: 'start-click-failed', err: String(e).slice(0, 180) });
}
await page.waitForTimeout(5000);
await snap('after-start');

for (let i = 0; i < 6; i++) {
  try {
    const opts = page.locator('button, [class*=option], [class*=answer]');
    const n = await opts.count();
    let clicked = false;
    for (let j = 0; j < n; j++) {
      const el = opts.nth(j);
      const t = ((await el.innerText().catch(() => '')) || '').trim();
      if (t && !/menu|login|sign in|cookie|accept|home|about|pricing|faq|contact/i.test(t)) {
        await el.click({ timeout: 8000 });
        clicked = true;
        break;
      }
    }
    if (!clicked) { log.push({ tag: 'q' + i, note: 'no clickable option' }); break; }
    await page.waitForTimeout(2500);
  } catch (e) {
    log.push({ tag: 'q' + i, err: String(e).slice(0, 140) });
    break;
  }
}
await snap('after-answers');
console.log(JSON.stringify(log));
return log;

